style.css:
/* Velvet Motion — All Websites */
/* i really want this to be global */

/* swap these values to customize the motion */
:root {
  --my-motion-speed: 250ms;
  --my-motion-easing: cubic-bezier(0.22, 1, 0.36, 1);
}

/* smooth transitions */
a,
button,
input,
textarea,
select,
img,
svg,
[role="button"],
[role="link"],
[tabindex] {
  transition:
    color var(--my-motion-speed) var(--my-motion-easing),
    background-color var(--my-motion-speed) var(--my-motion-easing),
    border-color var(--my-motion-speed) var(--my-motion-easing),
    box-shadow var(--my-motion-speed) var(--my-motion-easing),
    opacity var(--my-motion-speed) var(--my-motion-easing),
    transform var(--my-motion-speed) var(--my-motion-easing),
    filter var(--my-motion-speed) var(--my-motion-easing) !important;
}

/* interactive hover effects */
a:hover,
button:hover,
[role="button"]:hover {
  filter: brightness(1.08);
}

/* subtle button lift */
button:hover,
[role="button"]:hover {
  transform: translateY(-2px);
}

/* gentle image zoom */
img {
  transition: transform 350ms var(--my-motion-easing),
              filter 350ms var(--my-motion-easing) !important;
}

/* smooth image interaction */
img:hover {
  filter: saturate(1.08);
}

/* smooth focus */
input:focus,
textarea:focus,
select:focus {
  transition: box-shadow 200ms ease,
              border-color 200ms ease !important;
}

/* respect reduced-motion preferences */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
